-- READ-ONLY exact-timestamp value/units comparison over source-only union.
WITH u AS (SELECT a.dateTime ts FROM old_weewx.archive a LEFT JOIN loucka_reconstruction.archive r ON r.dateTime=a.dateTime WHERE a.dateTime>=UNIX_TIMESTAMP('2009-01-01') AND a.dateTime<UNIX_TIMESTAMP('2021-01-01') AND r.dateTime IS NULL UNION SELECT a.dateTime ts FROM weewx_WH1080.archive a LEFT JOIN loucka_reconstruction.archive r ON r.dateTime=a.dateTime WHERE a.dateTime>=UNIX_TIMESTAMP('2009-01-01') AND a.dateTime<UNIX_TIMESTAMP('2021-01-01') AND r.dateTime IS NULL)
SELECT YEAR(FROM_UNIXTIME(u.ts)) utc_year,COUNT(*) n,SUM(p.outTemp IS NOT NULL) p_temp,SUM(o.outTemp IS NOT NULL) old_temp,SUM(w.outTemp IS NOT NULL) wh_temp,SUM(p.outTemp IS NOT NULL AND o.outTemp IS NOT NULL AND p.outTemp=o.outTemp) p_old_temp_equal_nonnull,SUM(p.outTemp IS NOT NULL AND w.outTemp IS NOT NULL AND p.outTemp=w.outTemp) p_wh_temp_equal_nonnull,SUM(p.outHumidity IS NOT NULL) p_rh,SUM(o.outHumidity IS NOT NULL) old_rh,SUM(w.outHumidity IS NOT NULL) wh_rh,SUM(p.outHumidity IS NOT NULL AND o.outHumidity IS NOT NULL AND p.outHumidity=o.outHumidity) p_old_rh_equal_nonnull,SUM(p.outHumidity IS NOT NULL AND w.outHumidity IS NOT NULL AND p.outHumidity=w.outHumidity) p_wh_rh_equal_nonnull,SUM(p.rain IS NOT NULL) p_rain,SUM(o.rain IS NOT NULL) old_rain,SUM(w.rain IS NOT NULL) wh_rain,SUM(p.rain IS NOT NULL AND o.rain IS NOT NULL AND p.rain=o.rain) p_old_rain_equal_nonnull,SUM(p.rain IS NOT NULL AND w.rain IS NOT NULL AND p.rain=w.rain) p_wh_rain_equal_nonnull FROM u JOIN `pocasi-loucka.eu_old`.archive p ON p.dateTime=u.ts LEFT JOIN old_weewx.archive o ON o.dateTime=u.ts LEFT JOIN weewx_WH1080.archive w ON w.dateTime=u.ts GROUP BY utc_year ORDER BY utc_year;
